package shadow

import "testing"

func TestReady(t *testing.T) {
	if !Ready() {
		t.Fatal("baseline not ready")
	}
}

// Package shadow 是设备影子与远程升级的本地基线。
package shadow

// Ready 表示基线可以运行。
func Ready() bool { return true }

